import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const VILLES  = ['Tunis','Sfax','Sousse','Monastir','Nabeul','Bizerte','Kairouan','Ariana','Ben Arous','Mahdia'];
const NIVEAUX = ['Primaire','Collège 1ère','Collège 2ème','Collège 3ème','Lycée 1ère','Lycée 2ème','Lycée 3ème (Bac)','Université L1','Université L2','Université L3','Master'];

export default function Profile() {
  const { user } = useAuth();
  const [editing, setEditing] = useState(false);
  const [form, setForm] = useState({ nom: user?.nom || '', email: user?.email || '', ville: 'Sfax', niveau: 'Lycée 3ème (Bac)', telephone: '' });
  const [reservations, setReservations] = useState([]);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    if (user?.role === 'étudiant') {
      api.get('/api/etudiants/me').then(r => setForm(f => ({ ...f, ...r.data }))).catch(() => {});
      api.get('/api/reservations/mes-reservations').then(r => setReservations(r.data)).catch(() => {});
    }
  }, [user]);

  async function handleSave() {
    try {
      await api.put('/api/etudiants/me', form);
      setSaved(true); setTimeout(() => setSaved(false), 2000);
      setEditing(false);
    } catch (e) { alert('Erreur lors de la sauvegarde'); }
  }

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '10px 14px', fontSize: '.88rem', outline: 'none', width: '100%' };

  return (
    <div style={{ padding: 32 }}>
      <div style={{ fontFamily: 'Syne', fontSize: '1.2rem', fontWeight: 700, marginBottom: 24 }}>👤 Mon Profil</div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 24, alignItems: 'start' }}>
        {/* Profile card */}
        <div>
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 24, marginBottom: 20 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 20, marginBottom: 20 }}>
              <div style={{ width: 80, height: 80, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '2rem' }}>
                {user?.role === 'admin' ? '🛡' : user?.role === 'professeur' ? '👨‍🏫' : '👨‍🎓'}
              </div>
              <div>
                <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: '1.2rem' }}>{form.nom}</div>
                <div style={{ color: 'var(--text2)', fontSize: '.85rem' }}>{form.email}</div>
                <span style={{ background: 'rgba(108,99,255,.15)', color: '#6c63ff', fontSize: '.72rem', fontWeight: 600, padding: '2px 8px', borderRadius: 20, marginTop: 6, display: 'inline-block' }}>{user?.role}</span>
              </div>
            </div>

            {editing ? (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                <div><label style={{ fontSize: '.82rem', color: 'var(--text2)', display: 'block', marginBottom: 4 }}>Nom</label><input style={inp} value={form.nom} onChange={e => setForm(f => ({ ...f, nom: e.target.value }))} /></div>
                <div><label style={{ fontSize: '.82rem', color: 'var(--text2)', display: 'block', marginBottom: 4 }}>Téléphone</label><input style={inp} value={form.telephone || ''} onChange={e => setForm(f => ({ ...f, telephone: e.target.value }))} placeholder="+216 xx xxx xxx" /></div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                  <div><label style={{ fontSize: '.82rem', color: 'var(--text2)', display: 'block', marginBottom: 4 }}>Ville</label>
                    <select style={inp} value={form.ville} onChange={e => setForm(f => ({ ...f, ville: e.target.value }))}>
                      {VILLES.map(v => <option key={v}>{v}</option>)}
                    </select></div>
                  <div><label style={{ fontSize: '.82rem', color: 'var(--text2)', display: 'block', marginBottom: 4 }}>Niveau</label>
                    <select style={inp} value={form.niveau} onChange={e => setForm(f => ({ ...f, niveau: e.target.value }))}>
                      {NIVEAUX.map(n => <option key={n}>{n}</option>)}
                    </select></div>
                </div>
                <div style={{ display: 'flex', gap: 10, marginTop: 4 }}>
                  <button onClick={handleSave} style={{ flex: 1, padding: '9px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', border: 'none', borderRadius: 8, fontWeight: 600, cursor: 'pointer' }}>✅ Sauvegarder</button>
                  <button onClick={() => setEditing(false)} style={{ padding: '9px 16px', background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 8, color: 'var(--text)', cursor: 'pointer' }}>Annuler</button>
                </div>
              </div>
            ) : (
              <div>
                {[['📍 Ville', form.ville || '—'], ['🎓 Niveau', form.niveau || '—'], ['📞 Téléphone', form.telephone || '—']].map(([l, v]) => (
                  <div key={l} style={{ display: 'flex', justifyContent: 'space-between', padding: '10px 0', borderBottom: '1px solid var(--border)' }}>
                    <span style={{ fontSize: '.85rem', color: 'var(--text2)' }}>{l}</span>
                    <span style={{ fontSize: '.85rem', fontWeight: 500 }}>{v}</span>
                  </div>
                ))}
                <button onClick={() => setEditing(true)} style={{ marginTop: 16, padding: '8px 16px', background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 8, color: 'var(--text)', cursor: 'pointer', fontSize: '.82rem' }}>✏️ Modifier</button>
                {saved && <span style={{ marginLeft: 10, color: '#43e97b', fontSize: '.82rem' }}>✅ Sauvegardé !</span>}
              </div>
            )}
          </div>
        </div>

        {/* Reservations */}
        <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 24 }}>
          <div style={{ fontWeight: 600, marginBottom: 16 }}>📅 Mes Réservations</div>
          {reservations.length === 0 && <div style={{ textAlign: 'center', padding: 30, color: 'var(--text2)', fontSize: '.85rem' }}>Aucune réservation pour l'instant.</div>}
          {reservations.map(r => (
            <div key={r.id} style={{ background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, padding: 14, marginBottom: 12 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6 }}>
                <div style={{ fontWeight: 600, fontSize: '.88rem' }}>Réservation #{r.id}</div>
                <span style={{ background: r.statut === 'confirmé' ? 'rgba(67,233,123,.15)' : r.statut === 'en attente' ? 'rgba(255,177,67,.15)' : 'rgba(56,189,248,.15)', color: r.statut === 'confirmé' ? '#43e97b' : r.statut === 'en attente' ? '#ffb143' : '#38bdf8', fontSize: '.72rem', fontWeight: 600, padding: '2px 8px', borderRadius: 20 }}>{r.statut}</span>
              </div>
              <div style={{ fontSize: '.8rem', color: 'var(--text2)' }}>📅 {r.date_cours} à {String(r.heure_debut).slice(0, 5)}</div>
              {r.tarif_applique && <div style={{ fontSize: '.8rem', color: '#6c63ff', marginTop: 4 }}>💰 {r.tarif_applique} DT</div>}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
